breaking_changes.Adaptation_method:
Update your code to use the new options object syntax:
```js
// 2.x
Promise.promisify(fn, ctx);
// 3.0
Promise.promisify(fn, {context: ctx});
```

Instead of using Promise.defer(), use the Promise constructor pattern:
```js
// Old way
function delay(ms) {
    var resolver = Promise.defer();
    var now = Date.now();
    setTimeout(function(){
        resolver.resolve(Date.now() - now);
    }, ms);
    return resolver.promise;
}

// New way
function delay(ms) {
    return new Promise(function(resolve) {
        var now = Date.now();
        setTimeout(function(){
            resolve(Date.now() - now);
        }, ms);
    });
}
```
